package zone.moddev.mc.ironagearchitecture.client;

import java.io.IOException;
import java.util.*;
import net.minecraft.client.gui.*;
import net.minecraft.item.ItemStack;
import net.minecraft.nbt.NBTTagCompound;
import zone.moddev.mc.ironagearchitecture.roof.*;

/** The drawing remains on the server; this screen chooses tools and proposes edits. */
public final class RoofClipboardScreen extends GuiScreen {
    private final UUID id;
    private RoofPlan plan;private RoofNetwork.Reply state;private RoofFeature options=new RoofFeature();
    private int tool,selected=-1,left,top;private boolean preview=true,structure;
    private static final String[] TOOLS={"Window","Gabled dormer","Shed dormer","Mansard side","Select","Remove"};
    public RoofClipboardScreen(ItemStack stack){id=RoofClipboardItem.bound(stack);}
    @Override public void initGui(){left=(width-320)/2;top=(height-248)/2;buttonList.clear();button(0,8,20,148,"Tool");button(1,164,20,148,"Show preview");button(2,8,40,70,"Undo");button(3,84,40,72,"Redo");button(4,164,40,70,"Previous");button(5,242,40,70,"Next");for(int i=0;i<3;i++){button(10+i*2,8,64+i*20,18,"-");button(11+i*2,138,64+i*20,18,"+");}for(int i=0;i<5;i++)button(20+i,164,64+i*20,148,"Option");button(25,8,126,148,"Change selected");button(26,8,148,148,"Remove selected");button(27,8,176,148,"Rotate ridge");button(28,164,176,148,"Frame");button(29,8,196,148,"Height + half block");button(30,164,196,148,"Height - half block");button(31,164,216,148,"Page: features");for(int i=0;i<12;i++)button(40+i,i%2==0?8:164,64+(i/2)*22,148,"Setting");if(id!=null)RoofNetwork.clipboard(id,0,null,true,null);labels();}
    private void button(int id,int x,int y,int w,String text){buttonList.add(new GuiButton(id,left+x,top+y,w,16,text));}
    public void receive(RoofNetwork.Reply r){if(!r.clipboard||r.plan==null||!r.plan.id.equals(id))return;state=r;plan=r.plan.copy();preview=r.preview;tool=r.tool.getInteger("tool");selected=r.tool.hasKey("selected")?r.tool.getInteger("selected"):-1;if(r.tool.hasKey("options"))options=RoofFeature.read(r.tool.getCompoundTag("options"));labels();}
    private void labels(){for(GuiButton b:buttonList){if(b.id>=10&&b.id<=30)b.visible=!structure;if(b.id>=40)b.visible=structure;if(b.id==31)b.displayString=structure?"Page: roof":"Page: features";if(b.id>=40&&plan!=null){String[] settings={"Pitch: "+new String[]{"1:2","1:1","2:1"}[plan.pitch],"Floor: "+new String[]{"Auto","Inset","Wall top"}[plan.seat],"Eave A: "+plan.overhang[0]*.5,"Eave B: "+plan.overhang[1]*.5,"Gable A: "+plan.overhang[2]*.5,"Gable B: "+plan.overhang[3]*.5,"Roof height: "+plan.base*.5,"Clearance: "+plan.clearance*.5,"Eave drop: "+plan.drop*.25,"Edge: "+new String[]{"Exposed","Fascia","Boxed"}[plan.edge],"Frame: "+new String[]{"Traditional","Attic room","Open vault"}[plan.frame],"Mansard: "+new String[]{"None","Side A","Side B","Both"}[plan.mansard]};b.displayString=settings[b.id-40];}if(b.id==0)b.displayString="Tool: "+TOOLS[Math.min(5,tool)];if(b.id==1)b.displayString=preview?"Hide preview":"Show preview";if(b.id==20)b.displayString="Timber: "+zone.moddev.mc.ironagearchitecture.ArchitectureBlocks.WOODS[options.wood].replace('_',' ');if(b.id==21)b.displayString=options.finish==0?"Raw surround":"Limewashed surround";if(b.id==22)b.displayString=options.diamond?"Diamond leading":"Rectangular leading";if(b.id==23)b.displayString="Cheeks: "+new String[]{"Cob","Limewashed cob","Daub","Limewashed daub","Hanging tiles"}[options.wall];if(b.id==24)b.displayString="Roof: "+new String[]{"","Thatch","Slate","Clay tiles"}[options.cover];if(b.id==25||b.id==26)b.enabled=plan!=null&&selected>=0;if(b.id==28&&plan!=null)b.displayString="Frame: "+new String[]{"Traditional","Attic room","Open vault"}[plan.frame];}}
    private void sendOptions(){if(id==null)return;NBTTagCompound n=new NBTTagCompound();n.setInteger("tool",tool);n.setInteger("selected",selected);n.setTag("options",options.write());RoofNetwork.clipboard(id,9,null,preview,n);labels();}
    @Override protected void actionPerformed(GuiButton b)throws IOException{if(id==null||plan==null)return;if(b.id==31){structure=!structure;labels();return;}if(b.id==0){tool=(tool+1)%6;if(tool==0){options.width=1;options.height=1;}else if((tool==1||tool==2)&&options.width==1)options.width=3;sendOptions();return;}if(b.id==1){preview=!preview;RoofNetwork.clipboard(id,1,null,preview,null);return;}if(b.id==2||b.id==3){RoofNetwork.clipboard(id,b.id==2?6:7,null,preview,null);return;}if(b.id==4||b.id==5){if(plan.features.isEmpty())return;int index=0;for(int i=0;i<plan.features.size();i++)if(plan.features.get(i).id==selected)index=i;selected=plan.features.get(Math.floorMod(index+(b.id==4?-1:1),plan.features.size())).id;RoofFeature f=plan.features.get(Math.floorMod(index+(b.id==4?-1:1),plan.features.size()));options=f.copy();sendOptions();return;}if(b.id>=10&&b.id<=15){int delta=(b.id&1)==0?-1:1;if(b.id<=11)options.width=Math.max(1,Math.min(tool==1?5:30,options.width+delta));else if(b.id<=13)options.height=Math.max(1,Math.min(2,options.height+delta));else options.lift=Math.max(0,Math.min(4,options.lift+delta));sendOptions();return;}if(b.id>=20&&b.id<=24){if(b.id==20)options.wood=(options.wood+1)%6;if(b.id==21)options.finish^=1;if(b.id==22)options.diamond=!options.diamond;if(b.id==23)options.wall=(options.wall+1)%5;if(b.id==24)options.cover=options.cover%3+1;sendOptions();return;}RoofPlan next=plan.copy();RoofDrafts.upgrade(next);if(b.id>=40){if(b.id==40)next.pitch=(next.pitch+1)%3;if(b.id==41)next.seat=(next.seat+1)%3;if(b.id>=42&&b.id<=45)next.overhang[b.id-42]=(next.overhang[b.id-42]+1)%5;if(b.id==46)next.base=(next.base+1)%9;if(b.id==47)next.clearance=next.clearance>=12?4:next.clearance+1;if(b.id==48)next.drop=(next.drop+1)%5;if(b.id==49)next.edge=(next.edge+1)%3;if(b.id==50)next.frame=(next.frame+1)%3;if(b.id==51)next.mansard=(next.mansard+1)%4;}if(b.id==25){for(int i=0;i<next.features.size();i++)if(next.features.get(i).id==selected){RoofFeature old=next.features.get(i),f=options.copy();f.id=old.id;f.u=old.u;f.v=old.v;f.type=old.type;f.parent=old.parent;f.y=old.y;f.facing=old.facing;next.features.set(i,f);}}if(b.id==26)next.features.removeIf(f->f.id==selected||f.parent==selected);if(b.id==27)next.alongX=!next.alongX;if(b.id==28)next.frame=(next.frame+1)%3;if(b.id==29)next.base=Math.min(8,next.base+1);if(b.id==30)next.base=Math.max(0,next.base-1);RoofNetwork.clipboard(id,0,next,preview,null);}
    @Override public void drawScreen(int mx,int my,float partial){drawDefaultBackground();drawRect(left,top,left+320,top+248,0xffddd4c2);fontRendererObj.drawString("Architect's Clipboard",left+8,top+7,0x30291e);if(!structure){fontRendererObj.drawString("Width: "+options.width,left+32,top+68,0x30291e);fontRendererObj.drawString("Window height: "+options.height,left+32,top+88,0x30291e);fontRendererObj.drawString("Front lift: "+options.lift*.5,left+32,top+108,0x30291e);fontRendererObj.drawString("Selected: "+(selected<0?"none":selected),left+8,top+166,0x30291e);}String text=id==null?"Use this clipboard on a workbench first.":state==null?"Reading drawing...":state.status;fontRendererObj.drawString(fontRendererObj.trimStringToWidth(text,304),left+8,top+235,text.startsWith("Ready")?0x285635:0x82372a);super.drawScreen(mx,my,partial);}
    @Override public boolean doesGuiPauseGame(){return false;}
}
